 OR EXISTS(SELECT 1 FROM task_activities WHERE taskid BETWEEN 3040474 AND 3040476)
 OR EXISTS(SELECT 1 FROM achievement_criteria WHERE achievement_id=2075325 AND component_type=1 AND component_id BETWEEN 2075325 AND 2075327)
 OR EXISTS(SELECT 1 FROM reward_sets WHERE reward_set_id BETWEEN 3040474 AND 3040476)
 OR EXISTS(SELECT 1 FROM reward_sources WHERE source_type=2 AND source_id BETWEEN 3040474 AND 3040476)
 OR EXISTS(SELECT 1 FROM reward_options WHERE reward_set_id BETWEEN 3040474 AND 3040476)
 OR EXISTS(SELECT 1 FROM reward_option_entries WHERE reward_set_id BETWEEN 3040474 AND 3040476)
 OR EXISTS(SELECT 1 FROM rewards WHERE reward_id BETWEEN 304047401 AND 304047603)
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb reserved ID collision';END IF;
 IF(SELECT COUNT(*)FROM achievement_components WHERE achievement_id=2075325 AND component_type=1 AND sequence BETWEEN 1 AND 3 AND component_id=2075324+sequence)<>3
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb catalogue mismatch';END IF;
