-- Component: 2026_11_04_xorbb_npc_profiles.sql
IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()
     AND TABLE_NAME='npc_types' AND ENGINE='InnoDB')<>1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb profiles require transactional npc_types';
 END IF;
IF NOT((SELECT COUNT(*) FROM npc_types WHERE id IN(753900,753901,753902,753903))=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb reserved actor collision'; END IF;
