-- Component: 2026_11_04_xorbb_cell_keys.sql
IF (SELECT COUNT(*) FROM doors WHERE zone='xorbb' AND version=0
  AND ((doorid=93 AND name='OBJ_PRISON_DOOR_B')
   OR (doorid=94 AND name='OBJ_PRISON_DOOR_C'))
  AND opentype=6 AND lockpick=0 AND nokeyring=0 AND keyitem IN(0,66520))<>2
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb cell-door identity or lock policy differs'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=66520 AND name='Xorbb Prison Key')<>1
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb Prison Key is missing or differs'; END IF;
 UPDATE doors SET keyitem=66520 WHERE zone='xorbb' AND version=0
  AND ((doorid=93 AND name='OBJ_PRISON_DOOR_B')
   OR (doorid=94 AND name='OBJ_PRISON_DOOR_C')) AND keyitem=0;
 IF (SELECT COUNT(*) FROM doors WHERE zone='xorbb' AND version=0
  AND ((doorid=93 AND name='OBJ_PRISON_DOOR_B')
   OR (doorid=94 AND name='OBJ_PRISON_DOOR_C')) AND keyitem=66520)<>2
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb cell-key postimage differs'; END IF;
 END IF;

