-- Required component xorbb_mercenary_disabled.sql
IF(SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()
 AND TABLE_NAME IN('tasks','task_activities','achievement_criteria','reward_sets','reward_sources','reward_options','reward_option_entries','rewards')AND ENGINE='InnoDB')<>8
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Transactional content tables required';END IF;

 IF EXISTS(SELECT 1 FROM tasks WHERE id BETWEEN 3040477 AND 3040487)
 OR EXISTS(SELECT 1 FROM task_activities WHERE taskid BETWEEN 3040477 AND 3040487)
 OR EXISTS(SELECT 1 FROM achievement_criteria WHERE achievement_id=2075310)
 OR EXISTS(SELECT 1 FROM reward_sets WHERE reward_set_id BETWEEN 3040477 AND 3040487)
 OR EXISTS(SELECT 1 FROM reward_sources WHERE source_type=2 AND source_id BETWEEN 3040477 AND 3040487)
 OR EXISTS(SELECT 1 FROM reward_options WHERE reward_set_id BETWEEN 3040477 AND 3040487)
 OR EXISTS(SELECT 1 FROM reward_option_entries WHERE reward_set_id BETWEEN 3040477 AND 3040487)
 OR EXISTS(SELECT 1 FROM rewards WHERE reward_id BETWEEN 304047701 AND 304048799)
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved Xorbb Mercenary namespace collision';END IF;
 IF(SELECT COUNT(*)FROM achievement_components WHERE achievement_id=2075310 AND component_type=1 AND sequence BETWEEN 1 AND 11 AND component_id=2075309+sequence)<>11
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Xorbb Mercenary catalogue mismatch';END IF;
